// @ts-nocheck
// Store policies linked at the very bottom of every page (like Shopify's footer):
// Privacy policy, Refund policy, Terms of service, Shipping policy, Contact information.
// Policies for HunterRaid on Whop.

const STORE = 'HunterRaid'
const PRODUCT = 'HunterRaid Projector Hunting Game'
const UPDATED = 'October 2026'

const h2 = (t) => `<h2>${t}</h2>`
const p = (t) => `<p>${t}</p>`
const ul = (items) => `<ul>${items.map((i) => `<li>${i}</li>`).join('')}</ul>`
const contact = `<a href="/pages/contact">Contact</a>`
const page = (handle, title, parts) => ({ title, handle, url: `/policies/${handle}`, content: parts.join('\n') })

const privacy = page('privacy-policy', 'Privacy policy', [
  p(`<strong>Last updated: ${UPDATED}</strong>`),
  p(`${STORE} operates this store and website, including all related information, content, features, tools, products and services, in order to provide you, the customer, with a curated shopping experience (the "Services"). Our store is hosted, and our payments are processed, by Whop. This Privacy Policy describes how we collect, use, and disclose your personal information when you visit, use, or make a purchase or other transaction using the Services or otherwise communicate with us. If there is a conflict between our Terms of Service and this Privacy Policy, this Privacy Policy controls with respect to the collection, processing, and disclosure of your personal information.`),
  p(`Please read this Privacy Policy carefully. By using and accessing any of the Services, you acknowledge that you have read this Privacy Policy and understand the collection, use, and disclosure of your information as described in this Privacy Policy.`),
  h2('Personal Information We Collect or Process'),
  p(`When we use the term "personal information," we are referring to information that identifies or can reasonably be linked to you or another person. Personal information does not include information that is collected anonymously or that has been de-identified, so that it cannot identify or be reasonably linked to you. We may collect or process the following categories of personal information, including inferences drawn from this personal information, depending on how you interact with the Services, where you live, and as permitted or required by applicable law:`),
  ul([
    '<strong>Contact details</strong> including your name, address, billing address, shipping address, phone number, and email address.',
    '<strong>Financial information</strong> including credit card, debit card, and financial account numbers, payment card information, financial account information, transaction details, form of payment, payment confirmation and other payment details. Card details are collected and processed by Whop, our payment processor.',
    '<strong>Account information</strong> including your username, password, security questions, preferences and settings.',
    '<strong>Transaction information</strong> including the items you view, put in your cart, or purchase, return, exchange or cancel and your past transactions.',
    '<strong>Communications with us</strong> including the information you include in communications with us, for example, when sending a customer support inquiry.',
    '<strong>Device information</strong> including information about your device, browser, or network connection, your IP address, and other unique identifiers.',
    '<strong>Usage information</strong> including information regarding your interaction with the Services, including how and when you interact with or navigate the Services.',
  ]),
  h2('Personal Information Sources'),
  p('We may collect personal information from the following sources:'),
  ul([
    '<strong>Directly from you</strong> including when you create an account, visit or use the Services, communicate with us, or otherwise provide us with your personal information;',
    '<strong>Automatically through the Services</strong> including from your device when you use our products or services or visit our websites, and through the use of cookies and similar technologies;',
    '<strong>From our service providers</strong> including when we engage them to enable certain technology and when they collect or process your personal information on our behalf;',
    '<strong>From our partners or other third parties.</strong>',
  ]),
  h2('How We Use Your Personal Information'),
  p('Depending on how you interact with us or which of the Services you use, we may use personal information for the following purposes:'),
  ul([
    '<strong>Provide, Tailor, and Improve the Services.</strong> We use your personal information to provide you with the Services, including to perform our contract with you, to process your payments, to fulfill your orders, to send notifications to you related to your orders, to process purchases, returns, exchanges or other transactions, to arrange for shipping, to facilitate any returns and exchanges, to enable you to post reviews, and to create a customized shopping experience for you. This may include using your personal information to better tailor and improve the Services.',
    '<strong>Marketing and Advertising.</strong> We use your personal information for marketing and promotional purposes, such as to send marketing, advertising and promotional communications by email, text message or postal mail, and to show you online advertisements for products or services on the Services or other websites, including based on items you previously have purchased and other activity on the Services.',
    '<strong>Security and Fraud Prevention.</strong> We use your personal information to provide a secure payment and shopping experience, detect, investigate or take action regarding possible fraudulent, illegal, unsafe, or malicious activity, protect public safety, and to secure our services.',
    '<strong>Communicating with You.</strong> We use your personal information to provide you with customer support, to be responsive to you, to provide effective services to you and to maintain our business relationship with you.',
    '<strong>Legal Reasons.</strong> We use your personal information to comply with applicable law or respond to valid legal process, including requests from law enforcement or government agencies, to investigate or participate in civil discovery, potential or actual litigation, or other adversarial legal proceedings, and to enforce or investigate potential violations of our terms or policies.',
  ]),
  h2('How We Disclose Personal Information'),
  p('In certain circumstances, we may disclose your personal information to third parties for legitimate purposes subject to this Privacy Policy. Such circumstances may include:'),
  ul([
    'With Whop, vendors and other third parties who perform services on our behalf (e.g. IT management, payment processing, data analytics, customer support, cloud storage, fulfillment and shipping).',
    'With business and marketing partners to provide marketing services and advertise to you. Our business and marketing partners will use your information in accordance with their own privacy notices. Depending on where you reside, you may have a right to direct us not to share information about you to show you targeted advertisements and marketing based on your online activity. You can exercise this right by contacting us.',
    'When you direct, request us or otherwise consent to our disclosure of certain information to third parties, such as to ship you products or through your use of social media widgets or login integrations.',
    'With our affiliates or otherwise within our corporate group.',
    'In connection with a business transaction such as a merger or bankruptcy, to comply with any applicable legal obligations (including to respond to subpoenas, search warrants and similar requests), to enforce any applicable terms of service or policies, and to protect or defend the Services, our rights, and the rights of our users or others.',
  ]),
  h2('Relationship with Whop'),
  p(`The Services are hosted by Whop, which also processes payments at checkout. Whop collects and processes personal information about your access to and use of the Services, and the details you enter at checkout, in order to provide and improve the Services for you. Information you submit to the Services will be transmitted to and shared with Whop as well as third parties that may be located in countries other than where you reside. To learn more about how Whop uses your personal information and any rights you may have, you can visit the <a href="https://whop.com/legal/privacy" target="_blank" rel="noopener">Whop Privacy Policy</a>.`),
  h2('Third Party Websites and Links'),
  p('The Services may provide links to websites or other online platforms operated by third parties. If you follow links to sites not affiliated or controlled by us, you should review their privacy and security policies and other terms and conditions. We do not guarantee and are not responsible for the privacy or security of such sites, including the accuracy, completeness, or reliability of information found on these sites. Information you provide on public or semi-public venues, including information you share on third-party social networking platforms may also be viewable by other users of the Services and/or users of those third-party platforms without limitation as to its use by us or by a third party. Our inclusion of such links does not, by itself, imply any endorsement of the content on such platforms or of their owners or operators, except as disclosed on the Services.'),
  h2("Children's Data"),
  p('The Services are not intended to be used by children, and we do not knowingly collect any personal information about children under the age of majority in your jurisdiction. If you are the parent or guardian of a child who has provided us with their personal information, you may contact us using the contact details set out below to request that it be deleted. As of the Effective Date of this Privacy Policy, we do not have actual knowledge that we "share" or "sell" (as those terms are defined in applicable law) personal information of individuals under 16 years of age.'),
  h2('Security and Retention of Your Information'),
  p('Please be aware that no security measures are perfect or impenetrable, and we cannot guarantee "perfect security." In addition, any information you send to us may not be secure while in transit. We recommend that you do not use unsecure channels to communicate sensitive or confidential information to us.'),
  p('How long we retain your personal information depends on different factors, such as whether we need the information to provide you with Services, comply with legal obligations, resolve disputes or enforce other applicable contracts and policies.'),
  h2('Your Rights and Choices'),
  p('Depending on where you live, you may have some or all of the rights listed below in relation to your personal information. However, these rights are not absolute, may apply only in certain circumstances and, in certain cases, we may decline your request as permitted by law.'),
  ul([
    '<strong>Right to Access / Know.</strong> You may have a right to request access to personal information that we hold about you.',
    '<strong>Right to Delete.</strong> You may have a right to request that we delete personal information we maintain about you.',
    '<strong>Right to Correct.</strong> You may have a right to request that we correct inaccurate personal information we maintain about you.',
    '<strong>Right of Portability.</strong> You may have a right to receive a copy of the personal information we hold about you and to request that we transfer it to a third party, in certain circumstances and with certain exceptions.',
    '<strong>Right to Opt out of Sale or Sharing for Targeted Advertising.</strong> Depending on where you reside, you may have a right to opt out of the "sale" or "share" of your personal information or to opt out of the processing of your personal information for purposes considered to be "targeted advertising", as defined in applicable privacy laws. You can exercise this right by contacting us. If you visit our website with the Global Privacy Control opt-out preference signal enabled, depending on where you are, we will treat this as a request to opt-out for the device and browser that you use to visit the website. To learn more about Global Privacy Control, you can visit <a href="https://globalprivacycontrol.org/" target="_blank" rel="noopener">https://globalprivacycontrol.org/</a>. Other than the Global Privacy Control, we do not recognize other "Do Not Track" signals that may be sent from your web browser or device.',
    '<strong>Managing Communication Preferences.</strong> We may send you promotional emails, and you may opt out of receiving these at any time by using the unsubscribe option displayed in our emails to you. If you opt out, we may still send you non-promotional emails, such as those about orders that you have made.',
  ]),
  p('If you reside in the UK or European Economic Area, and subject to exceptions and limitations provided by local law, you may exercise the following rights in addition to the rights outlined above:'),
  ul([
    '<strong>Objection to Processing and Restriction of Processing:</strong> You may have the right to ask us to stop or restrict our processing of personal information for certain purposes.',
    '<strong>Withdrawal of Consent:</strong> Where we rely on consent to process your personal information, you have the right to withdraw this consent. If you withdraw your consent, this will not affect the lawfulness of any processing based on your consent before its withdrawal.',
  ]),
  p(`You may exercise any of these rights by contacting us using the contact details provided below.`),
  p('We will not discriminate against you for exercising any of these rights. We may need to verify your identity before we can process your requests, as permitted or required under applicable law. In accordance with applicable laws, you may designate an authorized agent to make requests on your behalf to exercise your rights. Before accepting such a request from an agent, we will require that the agent provide proof you have authorized them to act on your behalf, and we may need you to verify your identity directly with us. We will respond to your request in a timely manner as required under applicable law.'),
  h2('Complaints'),
  p('If you have complaints about how we process your personal information, please contact us using the contact details provided below. Depending on where you live, you may have the right to appeal our decision by contacting us, or lodge your complaint with your local data protection authority.'),
  h2('International Transfers'),
  p('Please note that we may transfer, store and process your personal information outside the country you live in.'),
  p("If we transfer your personal information out of the European Economic Area or the United Kingdom, we will rely on recognized transfer mechanisms like the European Commission's Standard Contractual Clauses, or any equivalent contracts issued by the relevant competent authority of the UK, as relevant, unless the data transfer is to a country that has been determined to provide an adequate level of protection."),
  h2('Changes to This Privacy Policy'),
  p('We may update this Privacy Policy from time to time, including to reflect changes to our practices or for other operational, legal, or regulatory reasons. We will post the revised Privacy Policy on this website, update the "Last updated" date and provide notice as required by applicable law.'),
  h2('Contact'),
  p(`For any questions about this Privacy Policy or to exercise your rights, please reach us through the ${contact} page of our website.`),
])

const refund = page('refund-policy', 'Refund policy', [
  p(`<strong>Refund and Return Policy</strong>`),
  p(`<strong>Last updated: ${UPDATED}</strong>`),
  p(`Please read this policy in full before you order. By placing an order with ${STORE} you confirm that you have read, understood and agreed to everything below. If you do not agree, please do not place an order.`),
  h2('1. Every order is a pre-order'),
  p(`Every ${STORE} is sold on pre-order and your order starts being prepared as soon as it is placed. Because of this, we are unable to cancel, change or refund an order once it has been placed, including in the minutes immediately after checkout. Please double check your order, your quantity and your shipping address before you pay.`),
  h2('2. All sales are final'),
  p(`All sales are final. We do not offer refunds, exchanges or store credit for change of mind, for ordering by mistake, for ordering the wrong quantity, for no longer wanting the item, for an item not arriving by a specific date or event, for not reading the pre-order notice, for impatience with the stated 2 to 4 week delivery estimate, or for any reason other than the item arriving damaged, broken or faulty as described in sections 5 and 6.`),
  h2('3. The product may look different in person'),
  p(`Our marketing photos and videos are produced to show the product at its best. The actual product may differ slightly in colour, shade, stitching detail, proportions, materials and finish from what appears in our photos, videos and advertising. By ordering you acknowledge and accept that the item you receive may look a bit different in person compared to our marketing content, and that these differences are not a defect and do not qualify for a refund, return or exchange.`),
  h2('4. Delivery times and delays'),
  p(`Every ${STORE} is sold on pre-order. The estimated delivery time of 2 to 4 weeks from purchase is clearly stated in the pre-order notice on the product page, and is repeated here. By placing an order you confirm that you have read and accepted the pre-order notice and the 2 to 4 week estimate. Not reading the pre-order notice, not noticing the estimated delivery time, or becoming impatient while your order is within the stated 2 to 4 week window is not grounds for a refund, cancellation, exchange or chargeback. Refund requests made on those grounds will be declined.`),
  p(`We do not guarantee delivery by any date, holiday or event, including Christmas. Preparation and shipping times are estimates only and can be affected by order volume, customs, carrier delays, weather and other factors outside our control. By ordering you acknowledge that delays may occur and you agree to accept them. A delay, however long, is not grounds for a refund, cancellation or chargeback. Once your order has shipped you will receive a tracking number by email, and any delivery questions after that point should be raised with the carrier using that tracking number.`),
  h2('5. Optional 1 Year Warranty (checkout add-on)'),
  p(`The 1 Year Warranty is an optional add-on offered at checkout. It covers <strong>faults, defects and items that stop working only</strong>. If you added it and it appears on your receipt, you are covered for <strong>12 months from the delivery date</strong> shown on your tracking (instead of the standard 48 hours in section 6) if your projector or shotguns:`),
  ul(['arrive damaged or broken, or', 'develop a fault or stop working through no fault of your own.']),
  p(`To claim, contact us through our ${contact} page within those 12 months with your order number and clear photos or a video showing the problem. If the claim is confirmed, we will repair or replace the faulty part, or refund the item price at our discretion.`),
  p(`The warranty does <strong>not</strong> cover delivery delays, change of mind, regret, ordering by mistake, batteries, or damage caused by misuse, drops, liquid, pets, wear and tear or weather. The add-on fee itself is non-refundable.`),
  h2('6. Damaged or faulty items'),
  p('If your item arrives damaged or faulty, to make a claim:'),
  ul([
    'Contact us within 48 hours of the delivery date shown on your tracking.',
    'Include your order number, a clear photo of the shipping box and label, and clear photos or a video showing the damage or the fault.',
    'Do not throw away any packaging until your claim is resolved.',
  ]),
  p('If the damage or fault is confirmed, we will, at our choice, send a replacement or refund you. Claims made after 48 hours of delivery, claims without proof, and claims for issues caused by misuse, wear and tear or weather are not covered.'),
  h2('7. Unopened returns'),
  p('If you have received your item and it is still completely unopened and unused, in its original sealed packaging, you may contact us within 7 days of delivery to request a return. Returns must be approved by us in writing before you send anything back. Return shipping is paid by the customer, items must arrive back to us in unopened, resalable condition, and a restocking fee of 20% will be deducted from any refund. Opened or used items cannot be returned under this section for hygiene reasons.'),
  h2('8. Wrong address, failed delivery and refused parcels'),
  p('You are responsible for entering a correct and complete shipping address. Orders shipped to an address you entered incorrectly, parcels returned to us as undeliverable, and parcels that are refused or uncollected are not eligible for a refund. If a parcel is returned to us, reshipping is at the customer’s expense.'),
  h2('9. Chargebacks and payment disputes'),
  p('If you have any problem with your order, please contact us first. We respond to every message and we resolve genuine damaged or faulty item claims. Filing a chargeback or payment dispute instead of contacting us, filing one while your order is being prepared or in transit, filing one because you did not read the pre-order notice or because your order is still within the stated 2 to 4 week delivery window, or filing one for a reason excluded by this policy, is a breach of this agreement. We respond to every dispute with the full order record, including this policy, your tracking history and all communication, and we reserve the right to refuse future orders from customers who file disputes in bad faith.'),
  h2('10. Order modifications'),
  p('Because preparation starts immediately, we cannot modify an order after it is placed. This includes changing the quantity or the shipping address. If you need to reach us about an order, do so before you place it.'),
  h2('11. Contact'),
  p(`For damaged or faulty item claims, or any other questions about your order, please reach us through the ${contact} page of our website and include your order number in your message. We aim to respond within 1 to 2 business days.`),
])

const S = (n, title) => h2(`SECTION ${n} - ${title}`)
const terms = page('terms-of-service', 'Terms of service', [
  h2('OVERVIEW'),
  p(`Welcome to ${STORE}! The terms "we", "us" and "our" refer to ${STORE}. ${STORE} operates this store and website, including all related information, content, features, tools, products and services in order to provide you, the customer, with a curated shopping experience (the "Services"). Our store is hosted, and our payments are processed, by Whop.`),
  p('The below terms and conditions, together with any policies referenced herein (these "Terms of Service" or "Terms") describe your rights and responsibilities when you use the Services.'),
  p('Please read these Terms of Service carefully, as they include important information about your legal rights and cover areas such as warranty disclaimers and limitations of liability.'),
  p(`By visiting, interacting with or using our Services, you agree to be bound by these Terms of Service and our <a href="/policies/privacy-policy">Privacy Policy</a>. If you do not agree to these Terms of Service or Privacy Policy, you should not use or access our Services.`),
  S(1, 'ACCESS AND ACCOUNT'),
  p('By agreeing to these Terms of Service, you represent that you are at least the age of majority in your state or province of residence, and you have given us your consent to allow any of your minor dependents to use the Services on devices you own, purchase or manage.'),
  p('To use the Services, including accessing or browsing our online stores or purchasing any of the products or services we offer, you may be asked to provide certain information, such as your email address, billing, payment, and shipping information. You represent and warrant that all the information you provide in our stores is correct, current and complete and that you have all rights necessary to provide this information.'),
  p('You are solely responsible for maintaining the security of your account credentials and for all of your account activity. You may not transfer, sell, assign, or license your account to any other person.'),
  S(2, 'OUR PRODUCTS'),
  p('We have made every effort to provide an accurate representation of our products and services in our online stores. However, please note that colors or product appearance may differ from how they may appear on your screen due to the type of device you use to access the store and your device settings and configuration.'),
  p('We do not warrant that the appearance or quality of any products or services purchased by you will meet your expectations or be the same as depicted or rendered in our online stores.'),
  p('All descriptions of products are subject to change at any time without notice at our sole discretion. We reserve the right to discontinue any product at any time and may limit the quantities of any products that we offer to any person, geographic region or jurisdiction, on a case-by-case basis.'),
  S(3, 'ORDERS'),
  p(`When you place an order, you are making an offer to purchase. ${STORE} reserves the right to accept or decline your order for any reason at its discretion. Your order is not accepted until ${STORE} confirms acceptance. We must receive and process your payment before your order is accepted. Please review your order carefully before submitting, as ${STORE} may be unable to accommodate cancellation requests after an order is accepted. In the event that we do not accept, make a change to, or cancel an order, we will attempt to notify you by contacting the e‑mail, billing address, and/or phone number provided at the time the order was made.`),
  p(`Your purchases are subject to return or exchange solely in accordance with our <a href="/policies/refund-policy">Refund Policy</a>.`),
  p('You represent and warrant that your purchases are for your own personal or household use and not for commercial resale or export.'),
  S(4, 'PRICES AND BILLING'),
  p('Prices, discounts and promotions are subject to change without notice. The price charged for a product or service will be the price in effect at the time the order is placed and will be set out in your order confirmation email. Unless otherwise expressly stated, posted prices do not include taxes, shipping, handling, customs or import charges.'),
  p('Prices posted in our online stores may be different from prices offered in physical stores or in online or other stores operated by third parties. We may offer, from time to time, promotions on the Services that may affect pricing and that are governed by terms and conditions separate from these Terms. If there is a conflict between the terms for a promotion and these Terms, the promotion terms will govern.'),
  p('You agree to provide current, complete and accurate purchase, payment and account information for all purchases made at our stores. You agree to promptly update your information, including your email address, credit card numbers and expiration dates, so that we can complete your transactions and contact you as needed.'),
  p('You represent and warrant that (i) the credit card information you provide is true, correct, and complete, (ii) you are duly authorized to use such credit card for the purchase, (iii) charges incurred by you will be honored by your credit card company, and (iv) you will pay charges incurred by you at the posted prices, including shipping and handling charges and all applicable taxes, if any.'),
  S(5, 'SHIPPING AND DELIVERY'),
  p(`We are not liable for shipping and delivery delays. All delivery times are estimates only and are not guaranteed. We are not responsible for delays caused by shipping carriers, customs processing, or events outside our control. Once we transfer products to the carrier, title and risk of loss passes to you. See our <a href="/policies/shipping-policy">Shipping Policy</a>.`),
  S(6, 'INTELLECTUAL PROPERTY'),
  p(`Our Services, including but not limited to all trademarks, brands, text, displays, images, graphics, product reviews, video, and audio, and the design, selection, and arrangement thereof, are owned by ${STORE}, its affiliates or licensors and are protected by U.S. and foreign patent, copyright and other intellectual property laws.`),
  p(`These Terms permit you to use the Services for your personal, non-commercial use only. You must not reproduce, distribute, modify, create derivative works of, publicly display, publicly perform, republish, download, store, or transmit any of the material on the Services without our prior written consent. Except as expressly provided herein, nothing in these Terms grants or shall be construed as granting a license or other rights to you under any patent, trademark, copyright, or other intellectual property of ${STORE}, Whop or any third party. Unauthorized use of the Services may be a violation of federal and state intellectual property laws. All rights not expressly granted herein are reserved by ${STORE}.`),
  p(`${STORE}'s names, logos, product and service names, designs, and slogans may not be used without the prior written permission of ${STORE}. Whop's name, logo, product and service names, designs and slogans are trademarks of Whop. All other names, logos, product and service names, designs, and slogans on the Services are the trademarks of their respective owners.`),
  S(7, 'OPTIONAL TOOLS'),
  p('You may be provided with access to customer tools offered by third parties as part of the Services, which we neither monitor nor have any control nor input.'),
  p('You acknowledge and agree that we provide access to such tools "as is" and "as available" without any warranties, representations or conditions of any kind and without any endorsement. We shall have no liability whatsoever arising from or relating to your use of optional third-party tools.'),
  p('Any use by you of the optional tools offered through the site is entirely at your own risk and discretion and you should ensure that you are familiar with and approve of the terms on which tools are provided by the relevant third-party provider(s).'),
  p('We may also, in the future, offer new features through the Services (including the release of new tools and resources). Such new features shall also be deemed part of the Services and are subject to these Terms of Service.'),
  S(8, 'THIRD-PARTY LINKS'),
  p('The Services may contain materials and hyperlinks to websites provided or operated by third parties (including any embedded third party functionality). We are not responsible for examining or evaluating the content or accuracy of any third-party materials or websites you choose to access. If you decide to leave the Services to access these materials or third party sites, you do so at your own risk.'),
  p("We are not liable for any harm or damages related to your access of any third-party websites, or your purchase or use of any products, services, resources, or content on any third-party websites. Please review carefully the third-party's policies and practices and make sure you understand them before you engage in any transaction. Complaints, claims, concerns, or questions regarding third-party products and services should be directed to the third-party."),
  S(9, 'RELATIONSHIP WITH WHOP'),
  p(`Our store is hosted and our payments are processed by Whop. However, any sales and purchases you make in our store are made directly with ${STORE}. By using the Services, you acknowledge and agree that Whop is not responsible for any aspect of any sales between you and ${STORE}, including any injury, damage, or loss resulting from purchased products and services.`),
  S(10, 'PRIVACY POLICY'),
  p(`All personal information we collect through the Services is subject to our <a href="/policies/privacy-policy">Privacy Policy</a>, and certain personal information may be subject to the <a href="https://whop.com/legal/privacy" target="_blank" rel="noopener">Whop Privacy Policy</a>. By using the Services, you acknowledge that you have read these privacy policies.`),
  p('Because the Services are hosted by Whop, Whop collects and processes personal information about your access to and use of the Services in order to provide and improve the Services for you. Information you submit to the Services will be transmitted to and shared with Whop as well as third parties that may be located in other countries than where you reside, in order to provide services to you.'),
  S(11, 'FEEDBACK'),
  p('If you submit, upload, post, email, or otherwise transmit any ideas, suggestions, feedback, reviews, proposals, plans, or other content (collectively, "Feedback"), you grant us a perpetual, worldwide, sublicensable, royalty-free license to use, reproduce, modify, publish, distribute and display such Feedback in any medium for any purpose, including for commercial use. We may, for example, use our rights under this license to operate, provide, evaluate, enhance, improve and promote the Services and to perform our obligations and exercise our rights under the Terms of Service.'),
  p('You also represent and warrant that: (i) you own or have all necessary rights to all Feedback; (ii) you have disclosed any compensation or incentives received in connection with your submission of Feedback; and (iii) your Feedback will comply with these Terms. We are and shall be under no obligation (1) to maintain your Feedback in confidence; (2) to pay compensation for your Feedback; or (3) to respond to your Feedback.'),
  p('We may, but have no obligation to, monitor, edit or remove Feedback that we determine in our sole discretion to be unlawful, offensive, threatening, libelous, defamatory, pornographic, obscene or otherwise objectionable or violates any party\'s intellectual property or these Terms of Service.'),
  p('You agree that your Feedback will not violate any right of any third-party, including copyright, trademark, privacy, personality or other personal or proprietary right. You further agree that your Feedback will not contain libelous or otherwise unlawful, abusive or obscene Feedback, or contain any computer virus or other malware that could in any way affect the operation of the Services or any related website. You may not use a false email address, pretend to be someone other than yourself, or otherwise mislead us or third-parties as to the origin of any Feedback. You are solely responsible for any Feedback you make and its accuracy. We take no responsibility and assume no liability for any Feedback posted by you or any third-party.'),
  S(12, 'ERRORS, INACCURACIES AND OMISSIONS'),
  p('Occasionally there may be information on or in the Services that contain typographical errors, inaccuracies or omissions that may relate to product descriptions, pricing, promotions, offers, product shipping charges, transit times and availability. We reserve the right to correct any errors, inaccuracies or omissions, and to change or update information or cancel orders if any information is inaccurate at any time without prior notice (including after you have submitted your order).'),
  S(13, 'PROHIBITED USES'),
  p(`You may access and use the Services for lawful purposes only. You may not access or use the Services, directly or indirectly: (a) for any unlawful or malicious purpose; (b) to violate any international, federal, provincial or state regulations, rules, laws, or local ordinances; (c) to infringe upon or violate our intellectual property rights or the intellectual property rights of others; (d) to harass, abuse, insult, harm, defame, slander, disparage, intimidate, or harm any of our employees or any other person; (e) to transmit false or misleading information; (f) to send, knowingly receive, upload, download, use, or re-use any material that does not comply with these Terms; (g) to transmit, or procure the sending of, any advertising or promotional material, including any "junk mail," "chain letter," "spam," or any other similar solicitation; (h) to impersonate or attempt to impersonate any other person or entity; or (i) to engage in any other conduct that restricts or inhibits anyone's use or enjoyment of the Services, or which, as determined by us, may harm ${STORE}, Whop or users of the Services, or expose them to liability.`),
  p('In addition, you agree not to: (a) upload or transmit viruses or any other type of malicious code that will or may be used in any way that will affect the functionality or operation of the Services; (b) reproduce, duplicate, copy, extract, sell, resell or exploit any portion of the Services; (c) collect or track the personal information of others; (d) spam, phish, pharm, or pretext the services; (e) use any robot, spider, scraping, data gathering and extraction tools, automatic devices or processes, AI tools (such as agentic AI) or automated or manual means to access the Services; or (f) interfere with, bypass, or circumvent the security or authorization features, robot exclusion headers, or other measures we employ to restrict access to the Services. We reserve the right to suspend, disable, or terminate your access at any time, without notice, if we determine that you have violated any part of these Terms.'),
  S(14, 'AGENTS'),
  p('14.1 This section ("Agent Terms") applies if you use, allow, enable, or cause the deployment of an Agent to access, use, or interact with any Services. "Agent" means any software or service that takes autonomous or semi-autonomous action on behalf of, or at the instruction of, any person or entity and that can be executed on behalf of or using persons device, without direct supervision.'),
  p('14.2 No Agent may access, use, or interact with Services unless, at all times, it identifies itself and operates in strict accordance with the requirements in section 14.4 below. In addition, no Agent may access, use, or interact with Services if we have requested that the Agent refrain from accessing, using, or interacting with any service.'),
  p('14.3 We may limit, including by technical measures, whether and how any Agent accesses, uses, and interacts with Services.'),
  p('14.4 Agents must: (i) in all HTTP/HTTPS requests, identify that the request is from an Agent and disclose the name of the Agent by including the following in the request\'s user agent string: "Agent/[agent name]"; (ii) not conceal or obfuscate that any access, use, or interactions are from an Agent, such as by (a) mimicking human behavior and interaction patterns, or (b) completing or circumventing CAPTCHAs or measures intended to distinguish computer use from humans, (iii) respond truthfully to any question or prompt seeking to determine if interactions are coming from a human or a computer, (iv) not circumvent or otherwise avoid any measure intended to block, limit, modify, or control whether and how Agents access, use, or interact with the Services.'),
  S(15, 'TERMINATION'),
  p('We may terminate this agreement or your access to the Services (or any part thereof) in our sole discretion at any time without notice, and you will remain liable for all amounts due up to and including the date of termination.'),
  p('The following sections will continue to apply following any termination: Intellectual Property, Feedback, Termination, Disclaimer of Warranties, Limitation of Liability, Indemnification, Severability, Waiver; Entire Agreement, Assignment, Governing Law, Privacy Policy, and any other provisions that by their nature should survive termination.'),
  S(16, 'DISCLAIMER OF WARRANTIES'),
  p('The information presented on or through the Services is made available solely for general information purposes. We do not warrant the accuracy, completeness, or usefulness of this information. Any reliance you place on such information is strictly at your own risk. We disclaim all liability and responsibility arising from any reliance placed on such materials by you or any other visitor to the Services, or by anyone who may be informed of any of its contents.'),
  p(`EXCEPT AS EXPRESSLY STATED BY ${STORE.toUpperCase()}, THE SERVICES AND ALL PRODUCTS OFFERED THROUGH THE SERVICES ARE PROVIDED 'AS IS' AND 'AS AVAILABLE' FOR YOUR USE, WITHOUT ANY REPRESENTATION, WARRANTIES OR CONDITIONS OF ANY KIND, EITHER EXPRESS OR IMPLIED, INCLUDING ALL IMPLIED WARRANTIES OR CONDITIONS OF MERCHANTABILITY, MERCHANTABLE QUALITY, FITNESS FOR A PARTICULAR PURPOSE, DURABILITY, TITLE, AND NON-INFRINGEMENT. WE DO NOT GUARANTEE, REPRESENT OR WARRANT THAT YOUR USE OF THE SERVICES WILL BE UNINTERRUPTED, TIMELY, SECURE OR ERROR-FREE. SOME JURISDICTIONS LIMIT OR DO NOT ALLOW THE DISCLAIMER OF IMPLIED OR OTHER WARRANTIES SO THE ABOVE DISCLAIMER MAY NOT APPLY TO YOU.`),
  S(17, 'LIMITATION OF LIABILITY'),
  p(`TO THE FULLEST EXTENT PROVIDED BY LAW, IN NO CASE SHALL ${STORE.toUpperCase()}, OUR PARTNERS, DIRECTORS, OFFICERS, EMPLOYEES, AFFILIATES, AGENTS, CONTRACTORS, SERVICE PROVIDERS OR LICENSORS, OR THOSE OF WHOP AND ITS AFFILIATES, BE LIABLE FOR ANY INJURY, LOSS, CLAIM, OR ANY DIRECT, INDIRECT, INCIDENTAL, PUNITIVE, SPECIAL, OR CONSEQUENTIAL DAMAGES OF ANY KIND, INCLUDING, WITHOUT LIMITATION, LOST PROFITS, LOST REVENUE, LOST SAVINGS, LOSS OF DATA, REPLACEMENT COSTS, OR ANY SIMILAR DAMAGES, WHETHER BASED IN CONTRACT, TORT (INCLUDING NEGLIGENCE), STRICT LIABILITY OR OTHERWISE, ARISING FROM YOUR USE OF ANY OF THE SERVICES OR ANY PRODUCTS PROCURED USING THE SERVICES, OR FOR ANY OTHER CLAIM RELATED IN ANY WAY TO YOUR USE OF THE SERVICES OR ANY PRODUCT, INCLUDING, BUT NOT LIMITED TO, ANY ERRORS OR OMISSIONS IN ANY CONTENT, OR ANY LOSS OR DAMAGE OF ANY KIND INCURRED AS A RESULT OF THE USE OF THE SERVICES OR ANY CONTENT (OR PRODUCT) POSTED, TRANSMITTED, OR OTHERWISE MADE AVAILABLE VIA THE SERVICES, EVEN IF ADVISED OF THEIR POSSIBILITY.`),
  S(18, 'INDEMNIFICATION'),
  p(`You agree to indemnify, defend and hold harmless ${STORE}, Whop, and our affiliates, partners, officers, directors, employees, agents, contractors, licensors, and service providers from any losses, damages, liabilities or claims, including reasonable attorneys' fees, payable to any third party due to or arising out of (1) your breach of these Terms of Service or the documents they incorporate by reference, (2) your violation of any law or the rights of a third party, or (3) your access to and use of the Services.`),
  p('We will notify you of any indemnifiable claim, provided that a failure to promptly notify will not relieve you of your obligations unless you are materially prejudiced. We may control the defense and settlement of such claim at your expense, including choice of counsel, but will not settle any claim requiring non-monetary obligations from you without your consent (not to be unreasonably withheld). You will cooperate in the defense of indemnified claims, including by providing relevant documents.'),
  S(19, 'SEVERABILITY'),
  p('In the event that any provision of these Terms of Service is determined to be unlawful, void or unenforceable, such provision shall nonetheless be enforceable to the fullest extent permitted by applicable law, and the unenforceable portion shall be deemed to be severed from these Terms of Service, such determination shall not affect the validity and enforceability of any other remaining provisions.'),
  S(20, 'WAIVER; ENTIRE AGREEMENT'),
  p('The failure of us to exercise or enforce any right or provision of these Terms of Service shall not constitute a waiver of such right or provision.'),
  p('These Terms of Service and any policies or operating rules posted by us on this site or in respect to the Service constitutes the entire agreement and understanding between you and us and governs your use of the Service, superseding any prior or contemporaneous agreements, communications and proposals, whether oral or written, between you and us (including, but not limited to, any prior versions of the Terms of Service).'),
  p('Any ambiguities in the interpretation of these Terms of Service shall not be construed against the drafting party.'),
  S(21, 'ASSIGNMENT'),
  p('You may not delegate, transfer or assign this Agreement or any of your rights or obligations under these Terms without our prior written consent, and any such attempt will be null and void. We may transfer, assign, or delegate these Terms and our rights and obligations without consent or notice to you.'),
  S(22, 'GOVERNING LAW'),
  p(`These Terms of Service and any separate agreements whereby we provide you Services shall be governed by and construed in accordance with the laws of the jurisdiction where ${STORE} is headquartered. You and ${STORE} consent to venue and personal jurisdiction in the courts of that jurisdiction.`),
  S(23, 'HEADINGS'),
  p('The headings used in this agreement are included for convenience only and will not limit or otherwise affect these Terms.'),
  S(24, 'CHANGES TO TERMS OF SERVICE'),
  p('You can review the most current version of the Terms of Service at any time on this page.'),
  p('We reserve the right, in our sole discretion, to update, change, or replace any part of these Terms of Service by posting updates and changes to our website. It is your responsibility to check our website periodically for changes. We will notify you of any material changes to these Terms in accordance with applicable law, and such changes will be effective on the date specified in the notice. Your continued use of or access to the Services following the posting of any changes to these Terms of Service constitutes acceptance of those changes.'),
])

const shipping = page('shipping-policy', 'Shipping policy', [
  p(`<strong>Shipping Policy</strong>`),
  p(`<strong>Last updated: ${UPDATED}</strong>`),
  p(`Please read this policy before you order. By placing an order with ${STORE} you confirm that you have read, understood and agreed to everything below, together with our <a href="/policies/refund-policy">Refund and Return Policy</a>.`),
  h2('1. Pre-order'),
  p('Every order is sold on pre-order. Your order starts being prepared as soon as your payment is confirmed, which is why orders cannot be cancelled or changed once placed. Your order is checked by hand and then shipped.'),
  h2('2. Processing and delivery times are estimates only'),
  p('Any processing or delivery time shown on our website, in our emails or in our advertising is an estimate, not a guarantee. Preparation time, carrier transit time and customs clearance can all vary, and times can be longer during busy periods such as the lead-up to Christmas. We do not guarantee delivery by any specific date, holiday or event, and we do not offer refunds, cancellations or compensation for orders that arrive later than estimated.'),
  h2('3. Christmas orders'),
  p('We will do our best to get Christmas orders out as quickly as we can, but we cannot guarantee arrival before Christmas or any other date. If you need your order for a specific event, please order as early as possible and understand that you are ordering at your own risk with regard to timing.'),
  h2('4. Tracking'),
  p('Once your order ships you will receive an email with a tracking number. Tracking information can take a few days to update after dispatch while the parcel moves through the carrier network, and it may show no movement for a period while in transit or customs. This is normal and does not mean your parcel is lost. For any delivery questions after dispatch, please check your tracking first.'),
  h2('5. Shipping destinations and costs'),
  p('We ship worldwide. Shipping costs, where applicable, are shown at checkout before you pay. If a destination is not available at checkout, we are unable to ship there.'),
  h2('6. Customs, duties and taxes'),
  p('International orders may be subject to import duties, taxes or customs fees charged by your country. These are set by your government, not by us, and they are the responsibility of the customer. We cannot predict these charges, we do not collect them, and we cannot refund an order because of them. Customs inspections can also add time to delivery, which is outside our control.'),
  h2('7. Your shipping address'),
  p("You are responsible for entering a correct and complete shipping address at checkout, including apartment or unit numbers. We cannot change an address once the order has been placed. Orders sent to an incorrect or incomplete address that you provided, and parcels returned to us as undeliverable, are not eligible for a refund. If a parcel comes back to us, reshipping will be at the customer's expense."),
  h2('8. Delivered, missing and stolen parcels'),
  p("Once the carrier marks your parcel as delivered, we consider it delivered. If tracking shows delivered but you cannot find your parcel, please check with household members, neighbours, your building's mail room and the carrier before contacting us, as parcels are often left in a safe place or collected by someone else. We are not responsible for parcels that are lost or stolen after the carrier has recorded delivery, and we recommend adding Shipping Protection at checkout if you would like cover for this."),
  p(`If tracking shows that your parcel has stopped moving for an extended period with no delivery scan, please contact us through the ${contact} page of our website with your order number and we will open an enquiry with the carrier. Carrier enquiries can take several weeks to resolve, and a replacement or refund will only be issued once the carrier confirms the parcel is lost.`),
  h2('9. Refused and uncollected parcels'),
  p("Parcels that are refused at the door, or not collected from a depot or collection point within the carrier's holding period, will be returned to us or disposed of by the carrier. These orders are not eligible for a refund."),
  h2('10. Multiple items'),
  p('If you order more than one item, or an item with add-ons, your items may ship separately and arrive at different times. Each shipment will have its own tracking number.'),
  h2('11. Shipping Protection'),
  p('Shipping Protection, when added at checkout, covers your order against loss or damage in transit. If a protected order is confirmed lost by the carrier or arrives damaged, we will replace it or refund it. Shipping Protection does not cover delays, customs charges, or incorrect addresses provided by the customer.'),
  h2('12. Contact'),
  p(`For any shipping questions, please reach us through the ${contact} page of our website and include your order number in your message. We aim to respond within 1 to 2 business days.`),
])

const contactInfo = page('contact-information', 'Contact information', [
  p('<strong>Contact Information</strong>'),
  p(`The fastest way to reach us is through the ${contact} section of our website. Click Contact in the menu, fill in the form with your name, your email address and your order number if you have one, and send your message. We aim to respond within 1 to 2 business days.`),
  p(`So we can find your order straight away, please mention that your enquiry is about the ${PRODUCT} in your message, along with your order number.`),
  p('Please include as much detail as you can in one message, including photos if your enquiry is about a damaged or faulty item, so we can help you in the first reply.'),
  p('Before you message us about a delivery, please check your tracking number from your shipping confirmation email first, as it will usually answer your question.'),
])

